import React from 'react';

const statusColors = {
    pending: 'bg-yellow-100 text-yellow-800 border-yellow-200',
    sending: 'bg-blue-100 text-blue-800 border-blue-200',
    done: 'bg-green-100 text-green-800 border-green-200'
};

const DonorCard = ({ donor, onClick, showStatus = true, isSelected = false }) => {
    const statusColor = statusColors[donor.status] || 'bg-gray-100 text-gray-800 border-gray-200';

    return (
        <div
            className={`border rounded-lg mb-3 transition-all ${isSelected ? 'border-green-500 shadow-md' : 'border-gray-200 hover:shadow-sm'}`}
            onClick={onClick}
        >
            <div className="p-4 flex justify-between items-center">
                <div className="flex-1">
                    <h3 className="font-medium text-lg">{donor.firstName} {donor.lastName}</h3>
                    <div className="text-sm text-gray-500 space-y-1 mt-1">
                        <p>WhatsApp: {donor.whatsappNumber}</p>
                        <p>Donation: {donor.price} DA</p>
                        <p>Type: {donor.type === 'sheep' ? 'Sheep' : 'Cow (1/7 share)'}</p>
                    </div>
                </div>

                {showStatus && (
                    <div className={`px-3 py-1 rounded-full text-xs font-medium ${statusColor}`}>
                        {donor.status === 'pending' && 'Pending'}
                        {donor.status === 'sending' && 'Processing'}
                        {donor.status === 'done' && 'Completed'}
                    </div>
                )}
            </div>
        </div>
    );
};

export default DonorCard;
